const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const svg=(path)=>`<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
const bookIcon=svg('<path d="M12 6c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V5c-4-1-7-1-10 1Z"/><path d="M12 6v15"/>');
const icons={home:svg('<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>'),read:bookIcon,books:svg('<path d="M4 3h4v18H4zM10 3h4v18h-4zM16 4l4-1 4 17-4 1z"/>'),saved:svg('<path d="M6 3h12v18l-6-4-6 4Z"/>'),about:svg('<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>')};
let prefs;try{prefs=JSON.parse(localStorage.getItem('serene-prefs'))||{}}catch{prefs={}}prefs={size:24,line:1.7,theme:'light',...prefs};
let library=null,db,bookmarks=[],position={book:0,chapter:0,scroll:0},selected=null,offline=false,installPrompt=null,importing=false;
const demo={format:'serene-scripture-v1',title:'King James Version · preview',source:'Public-domain KJV sample. Five verses only; this is not a complete chapter.',books:[{name:'Genesis',chapters:[{number:1,text:'1 In the beginning God created the heaven and the earth. 2 And the earth was without form, and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters. 3 And God said, Let there be light: and there was light. 4 And God saw the light, that it was good: and God divided the light from the darkness. 5 And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day.'}]}]};
const data=()=>library||demo;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function applyPrefs(){document.body.dataset.theme=prefs.theme;document.documentElement.style.setProperty('--size',prefs.size+'px');document.documentElement.style.setProperty('--line',prefs.line);$('#size-label').textContent=prefs.size+'px';document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===prefs.theme));document.querySelectorAll('[data-line]').forEach(b=>b.classList.toggle('selected',+b.dataset.line===prefs.line));try{localStorage.setItem('serene-prefs',JSON.stringify(prefs))}catch{toast('Preferences could not be saved on this device.')}}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('serene-scripture',1);r.onupgradeneeded=()=>r.result.createObjectStore('personal');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function get(key){return new Promise((resolve,reject)=>{const r=db.transaction('personal').objectStore('personal').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function put(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('personal','readwrite');tx.objectStore('personal').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function persist(key,value){if(db)put(key,value).catch(()=>toast('Could not save. Your device storage may be full.'))}
function current(){const books=data().books;position.book=Math.min(Math.max(0,position.book),books.length-1);const book=books[position.book];position.chapter=Math.min(Math.max(0,position.chapter),book.chapters.length-1);return{book,chapter:book.chapters[position.chapter]}}
function ref(){const{book,chapter}=current();return book.name+' '+chapter.number}
function verseParts(text){text=text.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,m=>' '+Array.from(m,c=>String('⁰¹²³⁴⁵⁶⁷⁸⁹'.indexOf(c))).join('')+' ');const parts=[];let next=1,last=0,start=0;const rx=/(^|\s)(\d{1,3})(?=\s|[A-Za-z“"‘])/g;let m;while((m=rx.exec(text))){if(+m[2]!==next)continue;if(next>1)parts.push({n:next-1,text:text.slice(start,m.index).trim()});else if(text.slice(0,m.index).trim())parts.push({n:null,text:text.slice(0,m.index).trim()});start=m.index+m[1].length+m[2].length;last=next;next++}if(last)parts.push({n:last,text:text.slice(start).trim()});else parts.push({n:null,text});return parts}
function isSaved(n){return bookmarks.some(x=>x.book===position.book&&x.chapter===position.chapter&&x.verse===n)}
function route(){return(location.hash.slice(1).split('/')[0]||'home')}
function go(r){if(location.hash==='#'+r)render();else location.hash=r}
function render(){const page=route();$('#nav').innerHTML=Object.entries(icons).map(([id,icon])=>`<a href="#${id}" ${page===id?'aria-current="page"':''} class="${page===id?'active':''}"><span aria-hidden="true">${icon}</span>${{home:'Home',read:'Read',books:'Books',saved:'Saved',about:'About'}[id]}</a>`).join('');$('.dock')?.remove();({home:renderHome,read:renderReader,books:renderBooks,saved:renderSaved,about:renderAbout}[page]||renderHome)();if(page!=='read')window.scrollTo(0,0)}
function renderHome(){const{chapter}=current();$('#app').innerHTML=`<section class="home-heading"><p class="eyebrow">YOUR PERSONAL SCRIPTURE LIBRARY</p><h1>A little space<br>for the Word.</h1><p class="muted">Open a chapter. Pick up where you left off.</p></section><section class="resume"><div class="resume-label"><span class="book-seal">${bookIcon}</span><p class="eyebrow">${library?'CONTINUE READING':'BEGIN YOUR READING'}</p></div><h2>${library?esc(ref()):'Your Bible, easier to read.'}</h2><p class="quote">${library?esc(chapter.text.replace(/^1\s*/,'').slice(0,150))+'…':'Bring your PDF into a page that fits your screen, with comfortable type and your place remembered.'}</p><button class="primary" id="hero-action">${library?'Open chapter':'Import Bible PDF'} <span aria-hidden="true">→</span></button><p class="resume-note">${library?'Your reading position is saved on this device.':'Processed privately on this device.'}</p></section><section class="library-links"><button data-go="books"><span>${icons.books}</span><span><strong>Browse the library</strong><small>${library?data().books.length+' imported books':'Explore the sample reader'}</small></span><span class="row-arrow">→</span></button><button data-go="saved"><span>${icons.saved}</span><span><strong>Saved passages</strong><small>${bookmarks.length?bookmarks.length+' bookmarks to return to':'Keep the words you want to revisit'}</small></span><span class="row-arrow">→</span></button></section>${library?`<p class="edition-note">${esc(data().title)}<br>Imported edition · Check important passages against the original PDF.</p>`:'<button class="preview-link" id="preview-read">Try the sample reader first →</button>'}<footer class="home-footer"><span>Made for everyday reading.</span><span>Built by <strong>Tegzy</strong></span></footer>`;$('#hero-action').onclick=()=>library?go('read'):chooseImport();$('#preview-read')?.addEventListener('click',()=>go('read'));bindGo()}

function renderReader(){const{book,chapter}=current();const parts=verseParts(chapter.text);$('#app').innerHTML=`<article class="reader"><div class="reader-top"><button class="reference" data-go="books">${esc(ref())} ▾</button><span class="status">${library?'Imported edition':'Reading preview'}</span></div><div class="reader-title"><p class="eyebrow">${esc(book.name)}</p><h1>Chapter ${chapter.number}</h1><div class="ornament" aria-hidden="true">${bookIcon}</div></div>${!library?'<p class="notice">Preview · Genesis 1:1–5 only. Import your PDF for the full reading collection.</p>':''}<div class="scripture">${parts.map((v,i)=>`<button class="verse ${isSaved(v.n)?'bookmarked':''}" data-part="${i}" aria-label="${v.n?'Verse '+v.n+'. ':''}${esc(v.text)}. Open passage actions">${v.n?`<sup>${v.n}</sup>`:''}${esc(v.text)}</button>`).join('')}</div><div class="chapter-end"><div class="ornament" aria-hidden="true">${bookIcon}</div><p class="muted">${library?'End of imported chapter '+chapter.number:'End of sample passage'}</p><div class="chapter-controls"><button id="prev-chapter">← Previous</button><button class="primary" id="next-chapter">Next chapter →</button></div>${library?'<p class="footnote">Text extracted from your PDF. The source edition determines wording and chapter numbering.</p>':'<button class="wide" id="reader-import">Import your Bible PDF</button>'}</div></article>`;const dock=document.createElement('aside');dock.className='dock';dock.setAttribute('aria-label','Reader tools');dock.innerHTML=`<button id="dock-settings" aria-label="Reading preferences">Aa</button><button data-go="books">${esc(ref())} ▾</button><button id="dock-save">${isSaved(null)?'Saved ✓':'Save chapter'}</button>`;document.body.append(dock);$('#dock-settings').onclick=openSettings;$('#dock-save').onclick=()=>{selected={book:position.book,chapter:position.chapter,verse:null,text:chapter.text.slice(0,240),reference:ref()};toggleBookmark();renderReader()};$('#prev-chapter').disabled=position.book===0&&position.chapter===0;$('#next-chapter').disabled=position.book===data().books.length-1&&position.chapter===book.chapters.length-1;$('#prev-chapter').onclick=()=>move(-1);$('#next-chapter').onclick=()=>move(1);$('#reader-import')?.addEventListener('click',chooseImport);document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const v=parts[+b.dataset.part];selected={book:position.book,chapter:position.chapter,verse:v.n,text:v.text,reference:ref()+(v.n?':'+v.n:'')};$('#passage-title').textContent=selected.reference;$('#passage-text').textContent=v.text;$('#save-passage').textContent=isSaved(v.n)?'Remove bookmark':'Bookmark';$('#passage').showModal()});bindGo();requestAnimationFrame(()=>window.scrollTo(0,position.scroll||0))}
function move(delta){const{book}=current();if(delta>0){if(position.chapter<book.chapters.length-1)position.chapter++;else if(position.book<data().books.length-1){position.book++;position.chapter=0}else return}else{if(position.chapter>0)position.chapter--;else if(position.book>0){position.book--;position.chapter=data().books[position.book].chapters.length-1}else return}position.scroll=0;persist('position',position);render()}
function renderBooks(){const bits=location.hash.split('/'),chosen=bits.length>1?Number(bits[1]):null;$('#app').innerHTML=`<p class="eyebrow">FIND YOUR NEXT CHAPTER</p><h1>The library</h1><p class="muted">${library?data().books.length+' books from your imported edition.':'Import your PDF to add its books and chapters.'}</p><input class="search" id="book-search" type="search" placeholder="Search books…" aria-label="Search books"><div id="book-list"></div>${library?'':'<button class="primary wide" id="books-import">Import Bible PDF</button>'}`;function list(q=''){const names=data().books.map((b,i)=>({b,i})).filter(({b})=>b.name.toLowerCase().includes(q.toLowerCase()));$('#book-list').innerHTML=names.length?names.map(({b,i})=>`<button class="book-row" data-book="${i}" aria-expanded="${chosen===i}"><span><strong>${esc(b.name)}</strong><small>${b.chapters.length} ${library?'chapters':'sample passage'}</small></span><span>${chosen===i?'−':'+'}</span></button>${chosen===i?`<div class="chapter-grid">${b.chapters.map((c,j)=>`<button data-chapter="${i},${j}" class="${position.book===i&&position.chapter===j?'active':''}">${c.number}</button>`).join('')}</div>`:''}`).join(''):'<p class="muted">No matching books.</p>';document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>go(chosen===+b.dataset.book?'books':'books/'+b.dataset.book));document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{const [book,chapter]=b.dataset.chapter.split(',').map(Number);position={book,chapter,scroll:0};persist('position',position);go('read')})}list();$('#book-search').oninput=e=>list(e.target.value);$('#books-import')?.addEventListener('click',chooseImport)}
function renderSaved(){$('#app').innerHTML=`<p class="eyebrow">WORDS TO RETURN TO</p><h1>Saved passages</h1><p class="muted">${bookmarks.length} bookmark${bookmarks.length===1?'':'s'}, kept on this device.</p>${bookmarks.length?bookmarks.map((b,i)=>`<section class="saved"><div class="saved-head"><h3>${esc(b.reference)}</h3><button data-remove="${i}" aria-label="Remove bookmark ${esc(b.reference)}">Remove</button></div><p class="quote">${esc(b.text)}</p><button class="primary" data-open="${i}">Open passage →</button></section>`).join(''):'<section class="empty"><span class="card-icon">${icons.saved}</span><h2>A place for your favourite words.</h2><p class="muted">Tap a passage while reading, then choose Bookmark.<br>It will be waiting for you here.</p><button class="primary" data-go="read">Start reading →</button></section>'}`;document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{bookmarks.splice(+b.dataset.remove,1);persist('bookmarks',bookmarks);renderSaved();toast('Bookmark removed')});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const x=bookmarks[+b.dataset.open];position={book:x.book,chapter:x.chapter,scroll:0};persist('position',position);go('read');requestAnimationFrame(()=>{const target=[...document.querySelectorAll('.verse')].find(v=>v.querySelector('sup')?.textContent===String(x.verse));target?.scrollIntoView({block:'center'})})});bindGo()}
function renderAbout(){$('#app').innerHTML=`<p class="eyebrow">CREATED WITH CARE</p><h1>A reader made<br>for my dad.</h1><p class="muted">A personal Ethiopian Bible reader, made to bring comfort and clarity to everyday reading.</p><section class="about-section"><h2>Built by Tegzy</h2><p>Made for my dad, and for everyone who appreciates a quiet page and comfortable text.</p><div class="actions"><button class="primary" id="share-app">Share app</button><button id="install-app">Add to home screen</button></div><p id="install-help" class="footnote"></p></section><section class="about-section"><h2>Your edition</h2><p>${library?esc(data().title):'No full edition imported yet.'}</p><p class="footnote">${library?esc(data().source||'Imported from your document.'):'The built-in preview contains five verses from the public-domain King James Version.'}</p><button id="about-import">${library?'Import a different PDF':'Import your Bible PDF'}</button><p class="footnote">Importing a new edition replaces the reading collection and clears bookmarks after your confirmation. Your file is processed in your browser and is not uploaded.</p></section><section class="about-section"><h2>Offline reading</h2><span class="status" id="offline-label">${offline?'App saved for offline use':'Offline setup not complete'}</span><p class="muted">Imported text is stored on this device. Save the app files too so it can reopen without a connection.</p><button id="cache-app">${offline?'Refresh offline files':'Save app for offline reading'}</button><p class="footnote">Browser storage can be cleared by your device. Keep your original PDF. Font downloads are optional; a system serif font works offline.</p></section><section class="about-section"><h2>Your data stays with you</h2><p>Reading position, bookmarks, and preferences stay in this browser. There is no cross-device sync.</p><button id="export-data">Back up my reading data</button><input id="restore-file" type="file" accept="application/json,.json" hidden><button id="restore-data">Restore backup</button><p class="footnote">Restoring a backup replaces this device’s reading collection, bookmarks, and position after confirmation.</p></section><section class="about-section"><h2>About the text</h2><p>This is an independent reader. It does not certify an edition’s completeness, translation, or canonical status.</p><p class="footnote">PDF extraction may introduce spacing errors or retain section headings. Check important passages against your original. No scripture is generated or rewritten by AI.</p></section><p class="footnote">Serene Scripture · Version 1.0<br>Built by Tegzy</p>`;$('#about-import').onclick=chooseImport;$('#share-app').onclick=shareApp;$('#install-app').onclick=install;$('#cache-app').onclick=cacheApp;$('#export-data').onclick=()=>{const blob=new Blob([JSON.stringify({format:'serene-backup-v1',library,bookmarks,position,prefs})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='serene-scripture-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#restore-data').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text());if(x.format!=='serene-backup-v1')throw Error('Not a Serene Scripture backup');if(x.library)validateLibrary(x.library);if(!Array.isArray(x.bookmarks)||!x.position||!Number.isInteger(x.position.book)||!Number.isInteger(x.position.chapter))throw Error('Invalid backup');if(!confirm('Replace your reading collection and bookmarks with this backup?'))return;library=x.library;bookmarks=x.bookmarks;position=x.position;if(x.prefs)prefs={size:Math.min(40,Math.max(18,+x.prefs.size||24)),line:+x.prefs.line===2?2:1.7,theme:['light','sepia','dark'].includes(x.prefs.theme)?x.prefs.theme:'light'};await put('library',library);await put('bookmarks',bookmarks);await put('position',position);applyPrefs();go('home');toast('Backup restored')}catch(err){toast('Could not restore: '+err.message)}}}
function bindGo(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}
function openSettings(){applyPrefs();$('#settings').showModal()}
function toggleBookmark(){const i=bookmarks.findIndex(x=>x.book===selected.book&&x.chapter===selected.chapter&&x.verse===selected.verse);if(i>=0){bookmarks.splice(i,1);toast('Bookmark removed')}else{bookmarks.unshift({...selected,created:Date.now()});toast('Passage bookmarked')}persist('bookmarks',bookmarks)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard')}catch{toast('Copy unavailable. You can select and copy the passage text.')}}
async function shareApp(){const url=location.origin+location.pathname;try{if(navigator.share)await navigator.share({title:'Serene Scripture · By Tegzy',text:'A comfortable Bible reader, built by Tegzy. Import your own PDF to read.',url});else await copy(url)}catch(e){if(e.name!=='AbortError')toast('Sharing unavailable on this browser')}}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else $('#install-help').textContent=/iPad|iPhone/.test(navigator.userAgent)?'In Safari, open Share, then choose Add to Home Screen.':'Open your browser menu and choose Install app or Add to Home screen. If unavailable, bookmark this page.'}
function chooseImport(){if(importing)return;if(!db){toast('Device storage unavailable. Try a normal browser tab outside private browsing.');return}$('#import-file').click()}
function validateLibrary(x){if(x.format!=='serene-scripture-v1'||!Array.isArray(x.books)||!x.books.length)throw Error('Invalid reading collection');for(const b of x.books)if(typeof b.name!=='string'||!Array.isArray(b.chapters)||!b.chapters.length||b.chapters.some(c=>!Number.isInteger(c.number)||typeof c.text!=='string'))throw Error('Invalid book or chapter data')}
async function parsePDF(file){const pdfjs=await import('./pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./pdf.worker.mjs';const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;let lines=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),text=await page.getTextContent();const rows=[];for(const item of text.items){if(!('str'in item)||!item.str.trim())continue;const y=item.transform[5];if(y<30)continue;let row=rows.find(r=>Math.abs(r.y-y)<5);if(!row){row={y,items:[]};rows.push(row)}row.items.push({x:item.transform[4],text:item.str})}rows.sort((a,b)=>b.y-a.y);for(const r of rows){const line=r.items.sort((a,b)=>a.x-b.x).map(x=>x.text).join(' ').replace(/\s+/g,' ').trim();if(!/^\d+$/.test(line))lines.push(line)}page.cleanup();if(p%5===0||p===pdf.numPages){$('#import-progress').value=p/pdf.numPages;$('#import-status').textContent='Reading page '+p+' of '+pdf.numPages+'…';await new Promise(r=>setTimeout(r,0))}}await pdf.destroy();const books=[];let active=null,book=null;for(const line of lines){let m=line.match(/^(.{1,90}?)\s*Chapter\s*(\d+)\s*$/i);if(/^The Letter of Jeremiah$/i.test(line))m=[line,'The Letter of Jeremiah','1'];if(/^Psalm\s*151$/i.test(line))m=[line,'Psalm 151','1'];if(m){const name=m[1].trim().replace(/\s*-\s*$/,'').replace(/^Psalms? Book \d+$/i,'Psalms').replace(/^Meqabian II$/,'Meqabyan II');if(!book||book.name!==name){book=books.find(b=>b.name===name);if(!book){book={name,chapters:[]};books.push(book)}}active=book.chapters.find(c=>c.number===+m[2]);if(!active){active={number:+m[2],text:''};book.chapters.push(active)}}else if(active){if(/^Conclusion$/i.test(line))break;active.text+=(active.text?' ':'')+line}}if(!books.length)throw Error('No book/chapter headings found. This edition may need a custom extraction.');return{format:'serene-scripture-v1',title:file.name.replace(/\.pdf$/i,''),source:'Text extracted from your PDF. Original wording retained; extraction has not been independently verified.',books}}
$('#import-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(library&&!confirm('Replace the current edition? Existing bookmarks and reading position will be cleared.'))return;importing=true;$('.dock')?.remove();$('#app').innerHTML='<p class="eyebrow">PREPARING YOUR READING SPACE</p><h1>Opening your Bible.</h1><p class="muted">This happens on your device. A large PDF may take a few minutes. Keep this screen open.</p><progress class="progress" id="import-progress" max="1" value="0"></progress><p id="import-status" role="status">Preparing the importer…</p>';$('#nav').style.pointerEvents='none';try{const result=/\.json$/i.test(f.name)?JSON.parse(await f.text()):await parsePDF(f);validateLibrary(result);await put('library',result);await put('bookmarks',[]);await put('position',{book:0,chapter:0,scroll:0});library=result;bookmarks=[];position={book:0,chapter:0,scroll:0};toast(result.books.length+' books imported. Ready to read.');location.hash='#home'}catch(err){toast('Import failed: '+err.message)}finally{importing=false;$('#nav').style.pointerEvents='';render()}};
async function cacheApp(){if(!('serviceWorker'in navigator)){toast('Offline caching is unavailable in this browser');return}const b=$('#cache-app');if(b){b.disabled=true;b.textContent='Saving app files…'}try{const reg=await navigator.serviceWorker.ready;const worker=reg.active;if(!worker)throw Error('Reload once to finish offline setup');await new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>reject(Error('Offline setup timed out. Try again.')),60000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve():reject(Error(e.data.error))};worker.postMessage('CACHE_APP',[channel.port2])});offline=true;if(route()==='about')renderAbout();toast('App ready for offline reading')}catch(e){if(b){b.disabled=false;b.textContent='Retry offline setup'}toast(e.message)}}
$('#settings-open').onclick=openSettings;$('#settings-close').onclick=()=>$('#settings').close();$('#settings-done').onclick=()=>$('#settings').close();$('#smaller').onclick=()=>{prefs.size=Math.max(18,prefs.size-2);applyPrefs()};$('#larger').onclick=()=>{prefs.size=Math.min(40,prefs.size+2);applyPrefs()};document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{prefs.theme=b.dataset.theme;applyPrefs()});document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{prefs.line=+b.dataset.line;applyPrefs()});$('#passage-close').onclick=()=>$('#passage').close();$('#save-passage').onclick=()=>{toggleBookmark();$('#passage').close();renderReader()};$('#copy-passage').onclick=()=>copy(selected.reference+'\n'+selected.text);$('#share-passage').onclick=async()=>{try{if(navigator.share)await navigator.share({title:selected.reference,text:selected.reference+'\n'+selected.text});else await copy(selected.reference+'\n'+selected.text)}catch(e){if(e.name!=='AbortError')toast('Sharing unavailable')}};
addEventListener('hashchange',()=>{if(!importing)render()});let scrollTimer;addEventListener('scroll',()=>{if(route()!=='read'||importing)return;clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{position.scroll=window.scrollY;persist('position',position)},250)},{passive:true});addEventListener('pagehide',()=>{if(route()==='read')persist('position',{...position,scroll:window.scrollY})});addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});applyPrefs();
try{db=await openDB();[library,bookmarks,position]=await Promise.all([get('library'),get('bookmarks'),get('position')]);bookmarks=bookmarks||[];position=position||{book:0,chapter:0,scroll:0};if(library)validateLibrary(library)}catch{library=null;bookmarks=[];position={book:0,chapter:0,scroll:0};toast('Device storage unavailable. Reading preview is still available.')}render();setTimeout(()=>$('#intro')?.remove(),1200);if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js');offline=await caches.has('serene-v2')}catch{}}
